// Never persisted: historical ledger state is authoritative only for this live session/scope.
const coachSettlementHistory = {
  coachSettlementReconciliationRequestId: 0,
  coachSettlementReconciliation: null,
  coachSettlementReconciliationUiState: "EMPTY",
  coachSettlementReconciliationLoading: false,
  coachSettlementReconciliationMessage: "",
};
let coachSettlementHistoryPending = null;

function resetCoachSettlementHistory() {
  coachSettlementHistory.coachSettlementReconciliationRequestId += 1;
  coachSettlementHistory.coachSettlementReconciliation = null;
  coachSettlementHistory.coachSettlementReconciliationUiState = "EMPTY";
  coachSettlementHistory.coachSettlementReconciliationLoading = false;
  coachSettlementHistory.coachSettlementReconciliationMessage = "";
  coachSettlementHistoryPending = null;
}

async function readCoachSettlementHistory(scope = coachSettlementReconciliationScope()) {
  return window.TennisNoteDataClient.rpc("tn_coach_monthly_settlement_reconciliation_state", {
    target_branch_id: scope.branchId,
    target_coach_role_id: scope.coachRoleId,
    target_month: scope.settlementMonth,
  });
}

async function syncCoachSettlementHistoryFromServer() {
  const client = window.TennisNoteDataClient;
  const scope = coachSettlementReconciliationScope();
  const profileId = String(state.liveProfileId || "");
  const session = client?.getSession?.()?.access_token;
  const signature = coachSettlementReconciliationScopeSignature(scope);
  // Token stays in memory and is never logged, serialized or attached to a receipt.
  const isCurrent = () => profileId === String(state.liveProfileId || "")
    && signature === coachSettlementReconciliationScopeSignature()
    && session === client?.getSession?.()?.access_token;
  if (!profileId || !scope.branchId || !scope.coachRoleId || !client?.rpc || !session) {
    resetCoachSettlementHistory();
    coachSettlementHistory.coachSettlementReconciliationUiState = "ERROR";
    coachSettlementHistory.coachSettlementReconciliationMessage = "현재 담당 코치 권한과 지점을 확인한 뒤 다시 시도해 주세요.";
    renderCoachSettlementHistory();
    return false;
  }
  if (coachSettlementHistoryPending?.signature === signature
    && coachSettlementHistoryPending.profileId === profileId
    && coachSettlementHistoryPending.session === session) return coachSettlementHistoryPending.promise;
  const requestId = ++coachSettlementHistory.coachSettlementReconciliationRequestId;
  coachSettlementHistory.coachSettlementReconciliation = null;
  coachSettlementHistory.coachSettlementReconciliationLoading = true;
  coachSettlementHistory.coachSettlementReconciliationUiState = "LOADING";
  coachSettlementHistory.coachSettlementReconciliationMessage = "";
  renderCoachSettlementHistory();
  const promise = (async () => {
    try {
      const raw = await readCoachSettlementHistory(scope);
      const result = Array.isArray(raw) ? raw[0] || null : raw;
      if (requestId !== coachSettlementHistory.coachSettlementReconciliationRequestId || !isCurrent()) return false;
      if (!coachSettlementReconciliationPayloadIsExact(result, scope)) throw Error("settlement_reconciliation_scope_mismatch");
      coachSettlementHistory.coachSettlementReconciliation = result;
      coachSettlementHistory.coachSettlementReconciliationUiState = String(result.state).toUpperCase();
      return true;
    } catch (error) {
      if (requestId !== coachSettlementHistory.coachSettlementReconciliationRequestId || !isCurrent()) return false;
      const contract = coachSettlementReconciliationErrorContract(error);
      coachSettlementHistory.coachSettlementReconciliation = null;
      coachSettlementHistory.coachSettlementReconciliationUiState = contract.state;
      coachSettlementHistory.coachSettlementReconciliationMessage = contract.message;
      return false;
    } finally {
      if (requestId === coachSettlementHistory.coachSettlementReconciliationRequestId) {
        if (!isCurrent()) resetCoachSettlementHistory();
        else {
          coachSettlementHistory.coachSettlementReconciliationLoading = false;
          coachSettlementHistoryPending = null;
        }
        renderCoachSettlementHistory();
      }
    }
  })();
  coachSettlementHistoryPending = { signature, profileId, session, promise };
  return promise;
}

// Private canonical validators: immutable confirmed history, no client calculation.
function coachSettlementReconciliationScopeMatches(value, scope = coachSettlementReconciliationScope()) {
  const received = value?.scope || {};
  return String(received.branchId || "") === scope.branchId
    && String(received.coachRoleId || "") === scope.coachRoleId
    && String(received.settlementMonth || "").slice(0, 10) === scope.settlementMonth;
}

function normalizeCoachSettlementReconciliationReason(value = "") {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060\u2066-\u2069\uFEFF]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function coachSettlementReconciliationReasonError(value = "") {
  const reason = normalizeCoachSettlementReconciliationReason(value);
  const length = Array.from(reason).length;
  if (length < 2 || length > 240) return "이의 사유를 2~240자로 입력해 주세요.";
  if (
    /[<>\u0000-\u001F\u007F]/.test(reason)
    || reason.includes("@")
    || /(?:https?:\/\/|www\.|javascript:|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i.test(reason)
    || /\d(?:[\s().+\-]*\d){6,}/.test(reason)
  ) return "개인정보나 연락처·링크를 제외하고 확인할 항목만 적어 주세요.";
  return "";
}

function coachSettlementReconciliationPayloadIsExact(value, scope = coachSettlementReconciliationScope()) {
  if (!value || typeof value !== "object" || Array.isArray(value) || !coachSettlementReconciliationScopeMatches(value, scope)) return false;
  const remoteState = String(value.state || "").toUpperCase();
  if (remoteState === "EMPTY") {
    return value.snapshot == null && value.confirmation == null && value.reconciliation == null;
  }
  if (!["PENDING", "ACKNOWLEDGED", "DISPUTED"].includes(remoteState)) return false;
  const snapshot = value.snapshot || {};
  const confirmation = value.confirmation || {};
  const reconciliation = value.reconciliation;
  const totals = snapshot.totals || {};
  const displayedTotalsAreExact = [
    totals.settledSessions,
    totals.settledMinutes,
    totals.totalSettlementAmount,
  ].every((item) => typeof item === "number" && Number.isFinite(item) && item >= 0);
  const exactSnapshot = Boolean(
    snapshot.snapshotId
    && Number.isInteger(snapshot.revision)
    && snapshot.revision > 0
    && String(snapshot.status || "").toLowerCase() === "calculated"
    && ["r3_monthly_settlement_v1", "r3_effective_settlement_v2"].includes(String(snapshot.calculationVersion || ""))
    && /^[0-9a-f]{64}$/i.test(String(snapshot.sourceFingerprint || ""))
    && displayedTotalsAreExact
    && confirmation.confirmationId
    && String(confirmation.status || "").toLowerCase() === "confirmed"
    && String(confirmation.confirmationVersion || "") === "r3_monthly_settlement_confirmation_v1"
    && !Number.isNaN(Date.parse(String(confirmation.confirmedAt || "")))
  );
  if (!exactSnapshot) return false;
  if (remoteState === "PENDING") return reconciliation == null;
  const responseReason = normalizeCoachSettlementReconciliationReason(reconciliation?.reason || "");
  const responseIsExact = remoteState === "ACKNOWLEDGED"
    ? !responseReason
    : !coachSettlementReconciliationReasonError(responseReason);
  return Boolean(
    reconciliation?.reconciliationId
    && String(reconciliation.status || "").toUpperCase() === remoteState
    && String(reconciliation.responseVersion || "") === "r3_monthly_settlement_coach_reconciliation_v1"
    && !Number.isNaN(Date.parse(String(reconciliation.respondedAt || "")))
    && responseIsExact
  );
}

function coachSettlementReconciliationErrorContract(error) {
  const raw = String(error?.payload?.message || error?.payload?.code || error?.message || "").toLowerCase();
  if (raw.includes("reason_length") || raw.includes("reason_sensitive") || raw.includes("acknowledgement_reason")) {
    return {
      state: "PENDING",
      message: "이의 사유를 안전한 내용으로 수정한 뒤 다시 저장해 주세요.",
      validation: raw.includes("reason_sensitive")
        ? "개인정보나 연락처·링크를 제외하고 확인할 항목만 적어 주세요."
        : "이의 사유를 2~240자로 입력해 주세요.",
    };
  }
  if (raw.includes("stale") || raw.includes("revision") || raw.includes("source_mismatch") || raw.includes("source_fingerprint")) {
    return {
      state: "STALE",
      message: "관리자 확정 계산본이 변경되었습니다. 최신 상태를 다시 확인해 주세요.",
      validation: "",
    };
  }
  if (
    raw.includes("conflict")
    || raw.includes("operation_key_reused")
    || raw.includes("scope_mismatch")
    || raw.includes("already")
  ) {
    return {
      state: "CONFLICT",
      message: "다른 화면의 응답과 상태가 겹쳤습니다. 서버 상태를 다시 확인해 주세요.",
      validation: "",
    };
  }
  if (raw.includes("approved_coach_scope_required") || raw.includes("authentication_required") || raw.includes("forbidden")) {
    return {
      state: "ERROR",
      message: "현재 담당 코치 권한과 지점을 확인할 수 없습니다. 다시 로그인한 뒤 확인해 주세요.",
      validation: "",
    };
  }
  if (raw.includes("pgrst202") || raw.includes("tn_coach_monthly_settlement_reconciliation")) {
    return {
      state: "ERROR",
      message: "코치 정산 확인 기능을 업데이트하는 중입니다. 잠시 후 다시 확인해 주세요.",
      validation: "",
    };
  }
  return {
    state: "ERROR",
    message: "확정 정산 상태를 불러오지 못했습니다. 네트워크를 확인하고 다시 시도해 주세요.",
    validation: "",
  };
}

function coachSettlementReconciliationStateLabel(value = coachSettlementHistory.coachSettlementReconciliationUiState) {
  return ({
    EMPTY: "확정 대기",
    LOADING: "확인 중",
    PENDING: "응답 대기",
    ACKNOWLEDGED: "확인 완료",
    DISPUTED: "이의 접수",
    STALE: "다시 확인 필요",
    CONFLICT: "상태 확인 필요",
    ERROR: "불러오기 실패",
  })[String(value || "").toUpperCase()] || "확정 대기";
}

function coachSettlementReconciliationTimeLabel(value = "") {
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime())
    ? "시각 확인 필요"
    : new Intl.DateTimeFormat("ko-KR", {
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    }).format(parsed);
}

function coachSettlementReconciliationDefaultMessage(uiState) {
  return ({
    EMPTY: "선택한 월의 관리자 확정 내역이 없습니다. 예상 정산과는 별도입니다.",
    LOADING: "관리자가 확정한 월 정산을 확인하고 있습니다.",
    PENDING: "관리자가 확정한 계산본입니다. 이 화면은 이력 조회만 제공하며 응답·확정·지급은 하지 않습니다.",
    ACKNOWLEDGED: "관리자 확정 정산을 확인했다고 응답했습니다.",
    DISPUTED: "이의 사유를 관리자에게 전달했습니다.",
    STALE: "관리자 확정 계산본이 변경되었습니다. 최신 상태를 다시 확인해 주세요.",
    CONFLICT: "다른 화면의 응답과 상태가 겹쳤습니다. 서버 상태를 다시 확인해 주세요.",
    ERROR: "확정 정산 상태를 불러오지 못했습니다. 다시 확인해 주세요.",
  })[uiState] || "관리자 확정 정산을 확인하고 있습니다.";
}

const refreshVisibleHistory = () => {
  if (!document.hidden && $("#coachSettlementModal")?.hidden === false) void syncCoachSettlementHistoryFromServer();
};
window.addEventListener("focus", refreshVisibleHistory);
document.addEventListener("visibilitychange", refreshVisibleHistory);

/* Existing settlement sheet: confirmed history is separate from the effective preview. */
.coach-settlement-history { display: grid; gap: 8px; border-top: 1px solid var(--line); margin-top: 16px; padding-top: 16px; min-width: 0; overflow-wrap: anywhere; }
.coach-settlement-history-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; min-width: 0; }
.coach-settlement-history-head span { border-radius: 999px; padding: 5px 9px; color: var(--muted); background: var(--wash); font-size: 12px; font-weight: 900; }
.coach-settlement-history p { margin: 0; color: var(--muted); font-size: 13px; line-height: 1.5; }
.coach-settlement-history-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.coach-settlement-history-summary[hidden] { display: none; }
.coach-settlement-history-summary > div { display: grid; gap: 4px; min-width: 0; border-radius: 9px; padding: 10px; background: color-mix(in srgb, var(--paper) 90%, var(--soft-green)); }
.coach-settlement-history-summary span, .coach-settlement-history-summary small { color: var(--muted); font-size: 12px; }
.coach-settlement-history-summary strong { color: var(--ink); font-size: 16px; }
.coach-settlement-history-summary-reason, .coach-settlement-reconciliation-summary-reason, .coach-settlement-reconciliation-summary-response { grid-column: 1 / -1; }
.coach-settlement-history button { min-height: 44px; font-size: 16px; white-space: normal; }
#coachSettlementModal button[data-close-coach-settlement] { min-height: 44px; font-size: 16px; }
#coachSettlementModal #coachSettlementMonth { min-height: 44px; font-size: 16px; }
@media (max-width: 430px) { .coach-settlement-history-summary { grid-template-columns: minmax(0, 1fr); } }

// Read-only extraction: response form and write controls intentionally not exported.
function renderCoachSettlementHistory() {
  const section = $("#coachSettlementReconciliation");
  if (!section) return;
  const uiState = String(coachSettlementHistory.coachSettlementReconciliationUiState || "EMPTY").toUpperCase();
  const payload = coachSettlementHistory.coachSettlementReconciliation || {};
  const snapshot = payload.snapshot || null;
  const confirmation = payload.confirmation || null;
  const reconciliation = payload.reconciliation || null;
  const payloadIsExact = coachSettlementReconciliationPayloadIsExact(payload);
  const busy = coachSettlementHistory.coachSettlementReconciliationLoading;
  section.dataset.state = uiState;
  section.setAttribute("aria-busy", String(busy));
  const badge = $("#coachSettlementReconciliationStateBadge");
  if (badge) badge.textContent = coachSettlementReconciliationStateLabel(uiState);
  const message = $("#coachSettlementReconciliationMessage");
  if (message) message.textContent = coachSettlementHistory.coachSettlementReconciliationMessage || coachSettlementReconciliationDefaultMessage(uiState);

  const summary = $("#coachSettlementReconciliationSummary");
  if (summary) {
    summary.innerHTML = "";
    summary.hidden = !payloadIsExact || !snapshot || !confirmation;
    if (payloadIsExact && snapshot && confirmation) {
      const appendSummary = (label, value, detail, className = "") => {
        const item = document.createElement("div");
        if (className) item.className = className;
        const labelNode = document.createElement("span");
        const valueNode = document.createElement("strong");
        const detailNode = document.createElement("small");
        labelNode.textContent = label;
        valueNode.textContent = value;
        detailNode.textContent = detail;
        item.append(labelNode, valueNode, detailNode);
        summary.appendChild(item);
      };
      const month = String(payload.scope?.settlementMonth || "").slice(0, 7);
      const [year, monthNumber] = month.split("-");
      appendSummary("확정 월", year && monthNumber ? `${Number(year)}년 ${Number(monthNumber)}월` : "월 확인 필요", `${Number(snapshot.revision) || 0}차 계산본 · ${snapshot.calculationVersion === "r3_effective_settlement_v2" ? "적용일별 v2" : "기존 v1"}`);
      appendSummary("정산 진행", `${Number(snapshot.totals?.settledSessions) || 0}회`, `${Number(snapshot.totals?.settledMinutes) || 0}분`);
      appendSummary("확정 정산액", formatCoachWon(snapshot.totals?.totalSettlementAmount), `관리자 확인 ${coachSettlementReconciliationTimeLabel(confirmation.confirmedAt)}`);
      if (uiState === "DISPUTED" && reconciliation?.reason) {
        appendSummary("이의 사유", String(reconciliation.reason), `응답 ${coachSettlementReconciliationTimeLabel(reconciliation.respondedAt)}`, "coach-settlement-reconciliation-summary-reason");
      } else if (uiState === "ACKNOWLEDGED") {
        appendSummary("코치 응답", "확인했습니다", coachSettlementReconciliationTimeLabel(reconciliation?.respondedAt), "coach-settlement-reconciliation-summary-response");
      }
    }
  }

  const retry = $("#coachSettlementReconciliationRetry");
  if (retry) {
    retry.hidden = !["STALE", "CONFLICT", "ERROR"].includes(uiState);
    retry.disabled = busy;
  }
}

